<?php
declare(strict_types=1);

const LC_ROOT = __DIR__ . '/..';
foreach ([LC_ROOT.'/.env', dirname(LC_ROOT).'/.env'] as $env) if (is_file($env)) foreach (file($env, FILE_IGNORE_NEW_LINES) as $line) if (preg_match('/^([A-Z][A-Z0-9_]*)=(.*)$/', trim($line), $m) && getenv($m[1])===false) putenv($m[1].'='.trim(trim($m[2]), "\"'"));
function lc_env(string $key,string $default=''): string { $value=getenv($key); return $value===false||$value===''?$default:$value; }
function lc_db(): PDO { static $db; if(!$db){$path=lc_env('LICENSE_DB_PATH',LC_ROOT.'/storage/licenses.sqlite'); if(!is_dir(dirname($path))) mkdir(dirname($path),0700,true); $db=new PDO('sqlite:'.$path,null,null,[PDO::ATTR_ERRMODE=>PDO::ERRMODE_EXCEPTION,PDO::ATTR_DEFAULT_FETCH_MODE=>PDO::FETCH_ASSOC]); $db->exec('PRAGMA foreign_keys=ON; PRAGMA busy_timeout=5000');} return $db; }
function q(string $sql,array $args=[]): PDOStatement{$s=lc_db()->prepare($sql);$s->execute($args);return $s;}
function one(string $sql,array $args=[]):?array{return q($sql,$args)->fetch()?:null;}
function esc(mixed $v):string{return htmlspecialchars((string)$v,ENT_QUOTES|ENT_SUBSTITUTE,'UTF-8');}
function csrf():string{if(session_status()!==PHP_SESSION_ACTIVE)session_start();return $_SESSION['csrf']??=bin2hex(random_bytes(24));}
function require_csrf():void{if(!hash_equals($_SESSION['csrf']??'',(string)($_POST['csrf']??'')))throw new RuntimeException('Invalid request token');}
function sales_schema():void{lc_db()->exec(<<<'SQL'
CREATE TABLE IF NOT EXISTS buyers(id INTEGER PRIMARY KEY,email TEXT NOT NULL UNIQUE COLLATE NOCASE,name TEXT NOT NULL DEFAULT '',password_hash TEXT,locale TEXT NOT NULL DEFAULT 'en',created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS orders(id INTEGER PRIMARY KEY,buyer_id INTEGER NOT NULL REFERENCES buyers(id) ON DELETE RESTRICT,reference TEXT NOT NULL UNIQUE,product TEXT NOT NULL,amount_minor INTEGER NOT NULL,currency TEXT NOT NULL,tax_amount_minor INTEGER NOT NULL DEFAULT 0,status TEXT NOT NULL DEFAULT 'pending' CHECK(status IN('pending','paid','failed','refunded','cancelled')),provider TEXT,provider_reference TEXT,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,paid_at TEXT);
CREATE TABLE IF NOT EXISTS payment_events(id INTEGER PRIMARY KEY,provider TEXT NOT NULL,event_key TEXT NOT NULL,payload TEXT NOT NULL,signature_valid INTEGER NOT NULL DEFAULT 0,processed_at TEXT,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,UNIQUE(provider,event_key));
CREATE TABLE IF NOT EXISTS invoices(id INTEGER PRIMARY KEY,order_id INTEGER NOT NULL UNIQUE REFERENCES orders(id) ON DELETE RESTRICT,invoice_number TEXT NOT NULL UNIQUE,customer_name TEXT NOT NULL,customer_email TEXT NOT NULL,currency TEXT NOT NULL,subtotal_minor INTEGER NOT NULL,tax_amount_minor INTEGER NOT NULL,total_minor INTEGER NOT NULL,status TEXT NOT NULL DEFAULT 'issued' CHECK(status IN('issued','void')),created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS support_tickets(id INTEGER PRIMARY KEY,buyer_id INTEGER NOT NULL REFERENCES buyers(id) ON DELETE CASCADE,subject TEXT NOT NULL,message TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'open' CHECK(status IN('open','pending','answered','closed')),created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS downloads(id INTEGER PRIMARY KEY,buyer_id INTEGER NOT NULL REFERENCES buyers(id) ON DELETE CASCADE,product TEXT NOT NULL,version TEXT NOT NULL,filename TEXT NOT NULL,url TEXT NOT NULL,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS rate_limits(bucket TEXT PRIMARY KEY,attempts INTEGER NOT NULL DEFAULT 0,window_started_at INTEGER NOT NULL);
CREATE INDEX IF NOT EXISTS orders_buyer_status ON orders(buyer_id,status,created_at DESC);
CREATE INDEX IF NOT EXISTS payment_events_processed ON payment_events(processed_at,created_at);
SQL
);try{lc_db()->exec('ALTER TABLE licenses ADD COLUMN buyer_id INTEGER REFERENCES buyers(id) ON DELETE SET NULL');}catch(Throwable $e){}lc_db()->exec('CREATE INDEX IF NOT EXISTS licenses_buyer ON licenses(buyer_id)');}
function setup():void{lc_db()->exec("CREATE TABLE IF NOT EXISTS admins(id INTEGER PRIMARY KEY,email TEXT UNIQUE NOT NULL,password_hash TEXT NOT NULL,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP); CREATE TABLE IF NOT EXISTS themes(id INTEGER PRIMARY KEY,name TEXT NOT NULL,locale TEXT NOT NULL DEFAULT 'global',payload TEXT NOT NULL DEFAULT '{}',status TEXT NOT NULL CHECK(status IN('draft','published')),created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP); CREATE TABLE IF NOT EXISTS licenses(id INTEGER PRIMARY KEY,product TEXT NOT NULL DEFAULT 'transport-cms',key_hash TEXT NOT NULL,key_hint TEXT NOT NULL UNIQUE,status TEXT NOT NULL DEFAULT 'active',domain_limit INTEGER NOT NULL DEFAULT 1,theme_id INTEGER REFERENCES themes(id) ON DELETE SET NULL,source TEXT NOT NULL DEFAULT 'manual',purchase_code_hash TEXT UNIQUE,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP); CREATE TABLE IF NOT EXISTS domains(id INTEGER PRIMARY KEY,license_id INTEGER NOT NULL REFERENCES licenses(id) ON DELETE CASCADE,domain TEXT NOT NULL,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,last_seen_at TEXT,UNIQUE(license_id,domain)); CREATE TABLE IF NOT EXISTS events(id INTEGER PRIMARY KEY,license_id INTEGER REFERENCES licenses(id) ON DELETE SET NULL,action TEXT NOT NULL,detail TEXT NOT NULL DEFAULT '',created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP); CREATE TABLE IF NOT EXISTS purchase_requests(id INTEGER PRIMARY KEY,name TEXT NOT NULL,email TEXT NOT NULL,company TEXT NOT NULL DEFAULT '',message TEXT NOT NULL DEFAULT '',product TEXT NOT NULL DEFAULT 'transport-cms',status TEXT NOT NULL DEFAULT 'new' CHECK(status IN('new','contacted','completed','closed')),created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP); CREATE TABLE IF NOT EXISTS theme_versions(id INTEGER PRIMARY KEY,theme_id INTEGER NOT NULL REFERENCES themes(id) ON DELETE CASCADE,version TEXT NOT NULL,payload TEXT NOT NULL,features TEXT NOT NULL DEFAULT '[]',status TEXT NOT NULL,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,UNIQUE(theme_id,version))");foreach(["ALTER TABLE themes ADD COLUMN version TEXT NOT NULL DEFAULT '1.0.0'","ALTER TABLE themes ADD COLUMN price_minor INTEGER NOT NULL DEFAULT 14900","ALTER TABLE themes ADD COLUMN license_type TEXT NOT NULL DEFAULT 'single-site'","ALTER TABLE themes ADD COLUMN preview_url TEXT NOT NULL DEFAULT ''","ALTER TABLE themes ADD COLUMN features TEXT NOT NULL DEFAULT '[]'"] as $migration){try{lc_db()->exec($migration);}catch(Throwable $e){}}sales_schema();}
function host(string $value):string{$value=strtolower(trim($value));$value=preg_replace('#^https?://#','',$value);$value=explode('/',$value,2)[0];$value=preg_replace('/:\d+$/','',$value);if(!preg_match('/^(?:[a-z0-9](?:[a-z0-9-]{0,61}[a-z0-9])?\.)+[a-z]{2,63}$/',$value))throw new RuntimeException('A valid public domain is required.');return $value;}
function key_parts(string $key):array{if(!preg_match('/^TDL-([0-9]+)-([A-Z0-9]{24})$/',strtoupper(trim($key)),$m))throw new RuntimeException('Invalid licence key format.');return [(int)$m[1],strtoupper($m[2])];}
function issue_key():array{$secret=strtoupper(bin2hex(random_bytes(12)));$id=(int)lc_db()->lastInsertId();return [$id,'TDL-'.$id.'-'.$secret,$secret];}
function api_json():array{$raw=file_get_contents('php://input')?:'';$json=json_decode($raw,true);return is_array($json)?$json:$_POST;}
function reply(array $data,int $status=200):never{http_response_code($status);header('Content-Type: application/json; charset=utf-8');header('Cache-Control: no-store');echo json_encode($data,JSON_UNESCAPED_SLASHES);exit;}
function rate_limit(string $bucket,int $limit=60,int $window=60):void{$now=time();$row=one('SELECT attempts,window_started_at FROM rate_limits WHERE bucket=?',[$bucket]);if(!$row||$now-(int)$row['window_started_at']>=$window){q('INSERT INTO rate_limits(bucket,attempts,window_started_at) VALUES(?,?,?) ON CONFLICT(bucket) DO UPDATE SET attempts=excluded.attempts,window_started_at=excluded.window_started_at',[$bucket,1,$now]);return;}$attempts=(int)$row['attempts']+1;if($attempts>$limit){header('Retry-After: '.max(1,$window-($now-(int)$row['window_started_at'])));reply(['active'=>false,'error'=>'Rate limit exceeded'],429);}q('UPDATE rate_limits SET attempts=? WHERE bucket=?',[$attempts,$bucket]);}
function licence_api(bool $activate):never{try{$ip=$_SERVER['REMOTE_ADDR']??'unknown';rate_limit(($activate?'activate':'check').':'.$ip);$input=api_json();[$id,$secret]=key_parts((string)($input['license_key']??''));$licence=one('SELECT * FROM licenses WHERE id=?',[$id]);if(!$licence||!password_verify($secret,$licence['key_hash'])||$licence['status']!=='active')throw new RuntimeException('Licence is not active.');$domain=host((string)($input['domain']??''));$bound=one('SELECT id FROM domains WHERE license_id=? AND domain=?',[$id,$domain]);if(!$bound){$count=(int)(one('SELECT count(*) count FROM domains WHERE license_id=?',[$id])['count']??0);if(!$activate||$count>=(int)$licence['domain_limit'])throw new RuntimeException('This domain is not permitted for the licence.');q('INSERT INTO domains(license_id,domain,last_seen_at) VALUES(?,?,datetime(\'now\'))',[$id,$domain]);q('INSERT INTO events(license_id,action,detail) VALUES(?,?,?)',[$id,'domain.activated',$domain]);}else q('UPDATE domains SET last_seen_at=datetime(\'now\') WHERE id=?',[$bound['id']]);$locale=preg_replace('/[^a-z-]/','',strtolower((string)($input['locale']??'global')));$theme=one("SELECT name,locale,payload FROM themes WHERE id=? AND status='published' AND locale IN (?, 'global') ORDER BY locale=? DESC LIMIT 1",[$licence['theme_id'],$locale,$locale]);reply(['active'=>true,'license'=>['product'=>$licence['product'],'domain'=>$domain,'domain_limit'=>(int)$licence['domain_limit']],'theme'=>$theme?['name'=>$theme['name'],'locale'=>$theme['locale'],'payload'=>json_decode($theme['payload'],true)]:null,'checked_at'=>gmdate('c')]);}catch(Throwable $e){reply(['active'=>false,'error'=>$e->getMessage()],422);}}
function envato_verify():never{try{$ip=$_SERVER['REMOTE_ADDR']??'unknown';rate_limit('envato:'.$ip,10,60);$token=lc_env('ENVATO_PERSONAL_TOKEN');if($token==='')throw new RuntimeException('Envato verification is not configured on this server.');$input=api_json();$code=trim((string)($input['purchase_code']??''));if(!preg_match('/^[a-f0-9-]{20,80}$/i',$code))throw new RuntimeException('A valid Envato purchase code is required.');$curl=curl_init('https://api.envato.com/v3/market/author/sale?code='.rawurlencode($code));curl_setopt_array($curl,[CURLOPT_RETURNTRANSFER=>true,CURLOPT_HTTPHEADER=>['Authorization: Bearer '.$token,'Accept: application/json'],CURLOPT_TIMEOUT=>10,CURLOPT_CONNECTTIMEOUT=>5]);$raw=curl_exec($curl);$status=(int)curl_getinfo($curl,CURLINFO_HTTP_CODE);$error=curl_error($curl);curl_close($curl);if($raw===false||$error!=='')throw new RuntimeException('Envato verification request failed.');$data=json_decode($raw,true);if($status!==200||!is_array($data))throw new RuntimeException('Envato rejected the purchase code.');$buyerEmail=filter_var((string)($data['buyer']??''),FILTER_VALIDATE_EMAIL);$product=mb_substr((string)($data['item']['name']??'transport-cms'),0,180);reply(['verified'=>true,'product'=>$product,'buyer'=>['email'=>$buyerEmail?:null],'verified_at'=>gmdate('c')]);}catch(Throwable $e){reply(['verified'=>false,'error'=>$e->getMessage()],422);}}
function logged_in():bool{return !empty($_SESSION['admin']);}
function login_required():void{if(!logged_in()){header('Location: ./login');exit;}}
function buyer():?array{return !empty($_SESSION['buyer'])?one('SELECT * FROM buyers WHERE id=?',[(int)$_SESSION['buyer']]):null;}
function buyer_required():array{$buyer=buyer();if(!$buyer){header('Location: ./account/login');exit;}return $buyer;}
function buyer_layout(string $title,string $body):never{echo '<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>'.esc($title).' · TofiDesk</title><style>body{font:16px/1.55 Arial,sans-serif;background:#f5f6f3;color:#08283a;margin:0}.bar{background:#06283a;color:#fff;padding:20px 5%;display:flex;gap:22px;align-items:center}.bar strong{margin-right:auto}.bar a{color:#fff}.wrap{max-width:1100px;margin:35px auto;padding:0 20px}.grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(240px,1fr));gap:18px}.card{background:#fff;border:1px solid #dfe6e8;border-radius:14px;padding:22px;margin-bottom:18px}label{display:block;font-weight:700;margin:12px 0}input,textarea{display:block;width:100%;box-sizing:border-box;padding:11px;margin-top:5px;border:1px solid #ccd8dc;border-radius:7px}button{background:#ff7c2c;border:0;border-radius:7px;padding:12px 16px;font-weight:700;cursor:pointer}table{width:100%;border-collapse:collapse}td,th{text-align:left;padding:10px;border-bottom:1px solid #e1e7e9}.muted{color:#61707b}</style><header class="bar"><strong>TOFIDESK BUYER</strong><a href="./">Dashboard</a><a href="./account/support">Support</a><a href="./account/logout">Sign out</a></header><main class="wrap">'.$body.'</main></html>';exit;}
