0px}.actions{display:flex;flex-wrap:wrap;gap:12px;margin-top:28px}.button{display:inline-flex;align-items:center;gap:8px;padding:13px 19px;border-radius:9px;background:var(--orange);font-weight:800;color:#173342}.button.ghost{color:white;background:#ffffff14;border:1px solid #ffffff55}.grid{display:grid;grid-template-columns:repeat(3,1fr);gap:18px}.card{background:white;border:1px solid var(--line);padding:25px;border-radius:15px;box-shadow:0 8px 26px #08283a0a}.card h2{font:800 23px Poppins;margin:0 0 9px;letter-spacing:-.5px}.card p{color:var(--muted);margin:0}.feature-icon{display:grid;place-items:center;width:42px;height:42px;border-radius:11px;color:#d75009;background:#fff0e6;font-size:21px;margin-bottom:18px}.theme-card{min-height:200px;position:relative;overflow:hidden;background:linear-gradient(140deg,#103547,#287187);color:white;border:0}.theme-card:nth-child(2){background:linear-gradient(140deg,#3b2b56,#af6b58)}.theme-card:nth-child(3){background:linear-gradient(140deg,#233b31,#7b9b68)}.theme-card p{color:#e2ecee}.theme-tag{display:inline-block;background:#ffffff22;border:1px solid #ffffff44;border-radius:20px;padding:4px 9px;font-size:12px;margin-bottom:45px}form.card{max-width:700px;margin:44px auto}label{font-weight:700;font-size:14px;display:block;margin-top:13px}input,textarea,select{font:inherit;width:100%;padding:13px;margin-top:5px;border:1px solid #ccd8dc;border-radius:8px;background:white}textarea{min-height:130px}button{cursor:pointer;border:0;border-radius:8px;background:var(--orange);color:#123342;font-weight:800;padding:13px 18px;margin-top:16px}table{width:100%;border-collapse:collapse}td,th{padding:11px;text-align:left;border-bottom:1px solid var(--line)}.section-title{font:800 31px Poppins;margin:50px 0 18px;letter-spacing:-1px}.site-foot{background:#061f2d;color:#d1e0e5;padding:35px 24px;text-align:center;font-size:14px}@media(max-width:760px){.nav{height:68px;padding:0 18px;gap:13px}.brand{font-size:17px}.nav>a:not(.nav-cta){display:none}.shell{padding:0 16px 42px}.hero{padding:42px 26px;margin:18px 0}.hero h1{letter-spacing:-1px}.hero p{font-size:16px}.grid{grid-template-columns:1fr}.section-title{font-size:27px}.card{padding:21px}}</style><header class="site-head"><nav class="nav"><a class="brand" href="./shop">TOFI<b>DESK</b> <span>Transportation</span></a>'.$nav.'</nav></header><main class="shell">'.$body.'</main><footer class="site-foot">© '.date('Y').' TofiDesk Transportation · Licensed software for transport businesses</footer></html>';exit;}
setup();$sessionPath=dirname(lc_env('LICENSE_DB_PATH',LC_ROOT.'/storage/licenses.sqlite')).'/sessions';if(!is_dir($sessionPath))mkdir($sessionPath,0700,true);session_save_path($sessionPath);session_start();$path=parse_url($_SERVER['REQUEST_URI']??'/',PHP_URL_PATH)?:'/';$script=$_SERVER['SCRIPT_NAME']??'/index.php';$base=str_ends_with($script,'/index.php')?rtrim(dirname($script),'/'):'';if($base!==''&&$base!=='/'&&str_starts_with($path,$base))$path=substr($path,strlen($base))?:'/';
if($path==='/api/v1/licenses/activate')licence_api(true);if($path==='/api/v1/licenses/check')licence_api(false);if($path==='/api/v1/envato/verify')envato_verify();
if($path==='/account/register'){if($_SERVER['REQUEST_METHOD']==='POST'){require_csrf();$email=filter_var(trim((string)($_POST['email']??'')),FILTER_VALIDATE_EMAIL);$name=trim((string)($_POST['name']??''));$password=(string)($_POST['password']??'');if(!$email||$name===''||strlen($password)<12)throw new RuntimeException('Name, valid email and a 12+ character password are required.');q('INSERT INTO buyers(email,name,password_hash) VALUES(?,?,?)',[$email,$name,password_hash($password,PASSWORD_DEFAULT)]);$_SESSION['buyer']=(int)lc_db()->lastInsertId();header('Location: ./account');exit;}buyer_layout('Create buyer account','<div class="card"><h1>Create buyer account</h1><form method="post"><input type="hidden" name="csrf" value="'.csrf().'"> <label>Name<input name="name" required></label><label>Email<input type="email" name="email" required></label><label>Password<input type="password" name="password" minlength="12" required></label><button>Create account</button></form><p class="muted">Already registered? <a href="./login">Sign in</a></p></div>');}
if($path==='/account/login'){if($_SERVER['REQUEST_METHOD']==='POST'){require_csrf();$a=one('SELECT * FROM buyers WHERE email=?',[strtolower(trim((string)($_POST['email']??'')))]);if($a&&$a['password_hash']&&password_verify((string)($_POST['password']??''),$a['password_hash'])){session_regenerate_id(true);$_SESSION['buyer']=$a['id'];header('Location: ./account');exit;}$error='<p class="muted">Invalid email or password.</p>';}buyer_layout('Buyer sign in',($error??'').'<div class="card"><h1>Buyer sign in</h1><form method="post"><input type="hidden" name="csrf" value="'.csrf().'"> <label>Email<input type="email" name="email" required></label><label>Password<input type="password" name="password" required></label><button>Sign in</button></form><p class="muted">New buyer? <a href="./register">Create an account</a></p></div>');}
if($path==='/account/logout'){unset($_SESSION['buyer']);header('Location: ./account/login');exit;}
if(str_starts_with($path,'/account')) {
    $buyer=buyer_required();
    if($path==='/account/support' && $_SERVER['REQUEST_METHOD']==='POST') {
        require_csrf(); $subject=mb_substr(trim((string)($_POST['subject']??'')),0,180); $message=mb_substr(trim((string)($_POST['message']??'')),0,5000);
        if($subject===''||$message==='') throw new RuntimeException('Subject and message are required.');
        q('INSERT INTO support_tickets(buyer_id,subject,message) VALUES(?,?,?)',[$buyer['id'],$subject,$message]); header('Location: ./support'); exit;
    }
    if($path==='/account/support') {
        $tickets=q('SELECT * FROM support_tickets WHERE buyer_id=? ORDER BY updated_at DESC',[$buyer['id']])->fetchAll(); $rows='';
        foreach($tickets as $t) $rows.='<tr><td>'.esc($t['subject']).'</td><td>'.esc($t['status']).'</td><td>'.esc($t['updated_at']).'</td></tr>';
        buyer_layout('Support','<h1>Support</h1><div class="card"><form method="post"><input type="hidden" name="csrf" value="'.csrf().'"> <label>Subject<input name="subject" required></label><label>Message<textarea name="message" required></textarea></label><button>Open ticket</button></form></div><div class="card"><table><tr><th>Subject</th><th>Status</th><th>Updated</th></tr>'.$rows.'</table></div>');
    }
    if($path==='/account') {
        $licenses=q('SELECT l.*,group_concat(d.domain, ", ") domains FROM licenses l LEFT JOIN domains d ON d.license_id=l.id WHERE l.buyer_id=? GROUP BY l.id ORDER BY l.id DESC',[$buyer['id']])->fetchAll(); $licenseRows='';
        foreach($licenses as $l) $licenseRows.='<tr><td>'.esc($l['product']).'</td><td>'.esc($l['status']).'</td><td>'.esc($l['domains']?:'No domain bound').'</td><td>'.(int)$l['domain_limit'].'</td></tr>';
        $orders=q('SELECT o.*,i.invoice_number FROM orders o LEFT JOIN invoices i ON i.order_id=o.id WHERE o.buyer_id=? ORDER BY o.created_at DESC',[$buyer['id']])->fetchAll(); $orderRows='';
        foreach($orders as $o) $orderRows.='<tr><td>'.esc($o['reference']).'</td><td>'.esc($o['product']).'</td><td>'.esc(strtoupper($o['currency'])).' '.number_format(((int)$o['amount_minor'])/100,2).'</td><td>'.esc($o['status']).'</td><td>'.esc($o['invoice_number']??'—').'</td></tr>';
        $downloads=q('SELECT * FROM downloads WHERE buyer_id=? ORDER BY created_at DESC',[$buyer['id']])->fetchAll(); $downloadRows='';
        foreach($downloads as $d) $downloadRows.='<tr><td>'.esc($d['product']).'</td><td>'.esc($d['version']).'</td><td><a href="'.esc($d['url']).'">'.esc($d['filename']).'</a></td></tr>';
        buyer_layout('Buyer dashboard','<h1>Welcome, '.esc($buyer['name']).'</h1><div class="grid"><div class="card"><h2>Products & licences</h2><p class="muted">Your licensed products and allowed domains.</p></div><div class="card"><h2>Downloads</h2><p>'.count($downloads).' available file(s)</p></div><div class="card"><h2>Support</h2><a href="./support">Open a support ticket →</a></div></div><div class="card"><h2>Licences and domains</h2><table><tr><th>Product</th><th>Status</th><th>Domains</th><th>Limit</th></tr>'.$licenseRows.'</table></div><div class="card"><h2>Orders and invoices</h2><table><tr><th>Reference</th><th>Product</th><th>Total</th><th>Status</th><th>Invoice</th></tr>'.$orderRows.'</table></div><div class="card"><h2>Downloads</h2><table><tr><th>Product</th><th>Version</th><th>File</th></tr>'.$downloadRows.'</table></div>');
